"use client";

import Button from "@/components/ui/Button";
import { GroupInput, InputAddon, InputGroup } from "@/components/ui/FormFields.tsx";

export default function OrderSummary() {
  return (
    <div className="flex flex-col gap-4 w-full">
      {/* Promo Coupon Card */}
      <div className="bg-[#FFFFFF] border border-[#DEE2E7] rounded-xl p-4 shadow-sm">
        <label className="text-sm font-normal text-[#505050] mb-2 block">Have a coupon?</label>
        <InputGroup className="shadow-xs">
          <GroupInput
            type="text"
            placeholder="Add coupon"
            className="rounded-l-lg"
          />
          <InputAddon
            side="right"
            asButton
            onClick={() => console.log("Coupon Applied")}
            className="bg-[#FFFFFF] hover:bg-gray-50 text-[#0067FF] font-medium border-l-0 px-4"
          >
            Apply
          </InputAddon>
        </InputGroup>
      </div>

      {/* Calculations Breakdown Card */}
      <div className="bg-[#FFFFFF] border border-[#DEE2E7] rounded-xl p-5 shadow-sm text-sm text-[#505050]">
        <div className="space-y-3 pb-4 border-b border-[#DEE2E7]">
          <div className="flex justify-between">
            <span>Subtotal:</span>
            <span className="text-[#1C1C1C] font-normal">$1403.97</span>
          </div>
          <div className="flex justify-between">
            <span>Discount:</span>
            <span className="text-[#FA3434] font-normal">- $60.00</span>
          </div>
          <div className="flex justify-between">
            <span>Tax:</span>
            <span className="text-[#00B517] font-normal">+ $14.00</span>
          </div>
        </div>

        <div className="pt-4 flex flex-col gap-4">
          <div className="flex justify-between items-baseline text-base font-semibold text-[#1C1C1C]">
            <span>Total:</span>
            <span className="text-xl">$1357.97</span>
          </div>

          <Button className="w-full rounded-lg bg-[#00B517] hover:bg-[#009A13] text-[#FFFFFF] py-3 px-5 font-medium text-base transition duration-150 ease-in-out text-center shadow-xs border-none">
            Checkout
          </Button>
        </div>

        {/* Payment Methods / Trust Badges Row */}
        <div className="flex items-center justify-center gap-2.5 mt-5">
          {[
            AmericanExpressIcon,
            MasterCardIcon,
            PayPalIcon,
            VisaIcon,
            ApplePayIcon,
          ].map((Icon, index) => (
            <div
              key={index}
              className="h-5.5 w-8.5 rounded-sm border border-[#DEE2E7] bg-[#FFFFFF] p-0.5 shadow-3xs flex items-center justify-center"
            >
              <Icon />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

